    mergeWorktree: {
        parameters: {
            query?: never;
            header: {
                /** @description Random opaque key representing one user intent. */
                "Idempotency-Key": components["parameters"]["IdempotencyKeyParameter"];
            };
            path: {
                worktreeId: string;
            };
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": components["schemas"]["MergeWorktree"];
            };
        };
        responses: {
            /** @description Merge attempt reached a stable result. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WorktreeMergeResponse"];
                };
            };
            /** @description Merge or Activation remains pending. */
            202: {
                headers: {
                    Location: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OperationEnvelope"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /**
             * @description The merger may not merge, as in the shared Forbidden response, or `CHECKS_REQUIRED`: the merger is an
             *     agent held to the declared checks, and not every one has passed on the current content.
             */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            404: components["responses"]["NotFound"];
            /**
             * @description The Worktree state does not allow a merge. `PAGE_REVIEW_REQUIRED`: a pending page's or file's author
             *     cannot write its target, so only a person signed in to the browser who sends `pageDraftIds` may merge. The
             *     message names the pages and files and the pull request URL. `PAGES_CHANGED`: `pageDraftIds` differs from the drafts this
             *     merge would publish, so the merger must review the pages again. The message names the pull request URL.
             *     A request that could get both gets `PAGE_REVIEW_REQUIRED`, which a newer review cannot clear outside the
             *     browser. `FILES_IN_TRASH`: the pull request still changes a file that is in Trash or deleted, which no merge
             *     writes. Every reader who may review it gets this, whatever else keeps them from merging. The message names those files,
             *     counts those the reader cannot see without their names or states, and says that its author can leave each one out with
             *     the Unit removal intent before anyone merges. Nothing changes.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
        };
    };
